create index market_audit_actor on public.market_audit(actor_id); create index market_sales_confirmer on public.market_sales(confirmed_by); create index market_sales_thread on public.market_sales(thread_id); drop policy market_public on public.market_listings; drop policy market_owner on public.market_listings; create policy market_public on public.market_listings for select to anon using(status in ('published','sold') and market_private.visible_seller(seller_id)); create policy market_read on public.market_listings for select to authenticated using(seller_id=(select auth.uid()) or (select market_private.is_admin()) or (status in ('published','sold') and market_private.visible_seller(seller_id))); drop policy thread_admin_metadata on public.market_threads; drop policy thread_read on public.market_threads; create policy thread_read on public.market_threads for select to authenticated using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()) or (select market_private.is_admin()));
